from pathlib import Path
from html import escape

ROOT = Path(__file__).parent
DIST = ROOT / 'dist'
IG = 'https://www.instagram.com/bakedbyadeela/'
NAV = [('index.html','Home'),('about.html','About me'),('how-it-works.html','How it works'),('flavours.html','Flavour menu'),('bouquets.html','Bouquets'),('celebration-cakes.html','Celebration cakes'),('weddings.html','Weddings'),('blog.html','Journal')]
arrow = '<svg class="arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true"><path d="M6 18 18 6M7 6h11v11"/></svg>'
def button(href,label,secondary=False):
    return f'<a class="button{" secondary" if secondary else ""}" href="{href}">{label}{arrow}</a>'
def link(href,label): return f'<a class="text-link" href="{href}">{label}{arrow}</a>'
def photo(name,alt,cls='',eager=False):
    return f'<figure class="{cls}"><img src="assets/{name}.jpg" alt="{alt}" width="1122" height="1402" {"fetchpriority=high" if eager else "loading=lazy"}><figcaption class="image-caption">Illustrative design</figcaption></figure>'
def brand(): return '<a class="brand" href="index.html" aria-label="Baked by Adeela home"><img class="brand-logo" src="assets/bakedbyadeela-logo.png" alt="Bakedbyadeela floral BA logo" width="1254" height="1254"></a>'
def cta(): return '<section class="cta blush center"><h2>A little imagination.<br>A beautiful <em>celebration.</em></h2><p>Tell me what you have in mind. Let’s make something lovely.</p>'+button('contact.html','Begin your enquiry')+'</section>'
def intro(title,desc): return f'<div class="wrap page-intro"><h1>{title}</h1><p>{desc}</p></div>'
def page(filename,title,desc,body):
    nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if url==filename else '')+f'>{label}</a>' for url,label in NAV)
    html=f'''<!doctype html>
<html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Baked by Adeela</title><meta name="description" content="{escape(desc)}"><meta name="theme-color" content="#faf7f1"><meta property="og:title" content="{escape(title)} | Baked by Adeela"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><meta property="og:image" content="https://bakedbyadeela.netlify.app/assets/bouquet.jpg"><link rel="icon" href="assets/bakedbyadeela-logo.png" type="image/png"><link rel="stylesheet" href="style.css"><script src="app.js" defer></script></head>
<body><a class="skip" href="#main">Skip to content</a><div class="announcement">Beautifully baked. Thoughtfully made. Uniquely yours.</div><header class="wrap"><div class="masthead"><div class="mast-note">Floral cupcakes<br>&amp; celebration cakes</div>{brand()}<a class="mast-link" href="contact.html">Let’s create something {arrow}</a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation" aria-label="Open navigation"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true"><path d="M3 7h18M3 12h18M3 17h18"/></svg></button></div><nav class="nav" id="navigation" aria-label="Main navigation">{nav}</nav></header>
<main id="main">{body}</main><footer class="footer"><div class="wrap"><div class="footer-grid"><div>{brand()}<p>Edible flowers. Beautiful details.<br>Made for life’s sweetest moments.</p><a class="text-link" href="{IG}" target="_blank" rel="noopener noreferrer">Follow @bakedbyadeela {arrow}</a></div><div><div class="footer-title">Explore</div><div class="footer-links"><a href="bouquets.html">Cupcake bouquets</a><a href="celebration-cakes.html">Celebration cakes</a><a href="weddings.html">Wedding cupcake bouquets</a><a href="flavours.html">Flavour menu</a></div></div><div><div class="footer-title">Let’s get acquainted</div><div class="footer-links"><a href="about.html">About Adeela</a><a href="how-it-works.html">How it works</a><a href="blog.html">The journal</a><a href="contact.html">Contact &amp; enquiries</a><a href="how-it-works.html#questions">Your questions</a></div></div></div><div class="footer-bottom"><span>© 2026 Baked by Adeela. Made with care.</span><span>Design preview · AI-created illustrative imagery · Draft menu</span></div></div></footer></body></html>'''
    (DIST/filename).write_text(html,encoding='utf-8')

collections=[('wedding','weddings.html','Wedding cupcake bouquets','Romantic little blooms for your biggest day. A beautiful detail, made to be shared.'),('bouquet','bouquets.html','Cupcake bouquets','A bouquet with a delicious secret. Delicate buttercream flowers for someone special.'),('cake','celebration-cakes.html','Celebration cakes','A centrepiece for the moments that deserve a little more magic.')]
cards=''.join(f'<article class="collection"><a href="{url}">{photo(im,title)}<h3>{title}</h3></a><p>{copy}</p>{link(url,"Explore the collection")}</article>' for im,url,title,copy in collections)
steps='<div class="journey"><article><h3>Share your occasion</h3><p>A birthday, a wedding, or a just-because gift. Tell me the date, your ideas, and who we’re celebrating.</p></article><article><h3>Make it your own</h3><p>We’ll discuss colours, flavours and all the little details, then confirm a design and quote together.</p></article><article><h3>Celebrate beautifully</h3><p>Once the details and arrangements are agreed, all that’s left is to look forward to your celebration.</p></article></div>'
page('index.html','Floral cupcakes & celebration cakes','Discover beautiful cupcake bouquets, celebration cakes and wedding cupcake bouquets by Baked by Adeela.',f'''<div class="wrap"><section class="hero"><div class="hero-copy"><h1>Flowers you can<br><em>fall in love with.</em><br>And eat.</h1><p>Delicate cupcake bouquets and celebration cakes, where the beauty of flowers meets the joy of something sweet.</p>{button('#collections','Discover the collections')}<div class="hero-tail">For the moments that deserve more</div></div>{photo('bouquet','Illustrative bouquet of blush, lilac and ivory buttercream flowers','hero-photo',True)}</section></div><div class="ribbon"><span>Inspired by flowers</span><span>Made for your occasion</span><span>Beautiful down to the last detail</span></div><section class="section" id="collections"><div class="wrap"><div class="section-heading"><h2>Something <em>beautiful,</em><br>for every occasion.</h2><p>From a thoughtful little gesture to a once-in-a-lifetime celebration. Find your perfect starting point.</p></div><div class="collections">{cards}</div></div></section><section class="section sage"><div class="wrap split">{photo('cake','Illustrative ivory cake with delicate pink and lilac floral details')}<div class="split-copy"><h2>A love of flowers.<br>A passion for<br><em>beautiful baking.</em></h2><p>Welcome to Baked by Adeela — a little world of floral cupcakes, soft colours and thoughtful celebrations.</p><p>I believe the loveliest cakes should feel personal. A favourite colour, a meaningful occasion, a detail that is unmistakably you.</p><div class="signature">With love, Adeela</div>{link('about.html','Meet the maker')}</div></div></section><section class="section"><div class="wrap"><div class="section-heading"><h2>From your first idea<br>to the <em>final flourish.</em></h2>{link('how-it-works.html','Your customer journey')}</div>{steps}</div></section>{cta()}''')

page('about.html','About me','Meet the creative vision behind Baked by Adeela.',intro('The heart behind<br>the <em>buttercream.</em>','A little introduction to the world of Baked by Adeela.')+f'''<section class="section"><div class="wrap split">{photo('cake','Illustrative floral buttercream cake')}<div class="split-copy"><h2>Hello, I’m <em>Adeela.</em></h2><p>Welcome to my little corner of beautiful baking. Baked by Adeela brings together two things that belong so wonderfully together: the delicacy of flowers and the happiness of a celebration.</p><p>From soft, romantic cupcake bouquets to a cake that takes centre stage, the starting point is always your occasion — and the feeling you want to create.</p><p>A palette you love. A flower that means something. A thoughtful gift that says what words sometimes can’t. Those are the details that make a design feel like yours.</p><div class="signature">Something lovely, just for you.</div>{link('contact.html','Let’s talk about your occasion')}<p class="note">Introductory studio copy for this preview. Adeela’s personal story and portrait will be added here.</p></div></div></section><section class="section lilac"><div class="wrap center"><h2>Small details.<br><em>Wonderful memories.</em></h2><p>Explore a collection, find a colour that speaks to you, and imagine the moment you’ll share it.</p>{button('bouquets.html','Explore cupcake bouquets')}</div></section>''')

faqs=[('How do I make an enquiry?','Use the contact page to put your ideas together, then send your message to @bakedbyadeela on Instagram. Please include your date and the kind of creation you have in mind.'),('How much notice should I give?','Enquire as soon as you have a celebration date. Availability and the time needed for your design will be confirmed directly before an order is agreed.'),('Can I choose my colours and flowers?','Share your palette, favourite flowers or inspiration with your enquiry. The final design and what is achievable will be discussed with you.'),('How much will my order cost?','A personalised quote can be confirmed after the size, design and other details are discussed. This preview does not include a confirmed price list.'),('Can you accommodate dietary requirements?','Mention any allergies or dietary needs before ordering. Ingredients, cross-contact risks and suitability must be confirmed directly; this website does not promise allergen-free products.'),('Is collection or delivery available?','Ask about collection or delivery when enquiring. The location, timing, any delivery charge and safe transport arrangements need to be confirmed with Adeela.')]
page('how-it-works.html','How it works','Your journey from a first idea to a beautiful cake or cupcake bouquet.',intro('Your idea.<br>Our <em>lovely journey.</em>','A few thoughtful steps from “I have an idea” to a celebration that feels beautifully yours.')+f'<section class="section"><div class="wrap">{steps}<div class="notice">Your date, design, price and fulfilment arrangements are confirmed directly. An enquiry does not reserve a date or place an order.</div></div></section><section class="section sage" id="questions"><div class="wrap"><h2 class="center">A few things you<br>might be <em>wondering.</em></h2><div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faqs)+'</div></div></section>'+cta())

flavours=[('Vanilla bean','classic','#eadbc0','A delicate vanilla sponge with silky vanilla buttercream. Simple, soft and endlessly lovely.'),('Chocolate velvet','classic','#9b7662','Rich chocolate sponge paired with smooth chocolate buttercream. A little indulgence in every bite.'),('Lemon & elderflower','fruit','#e6d596','Bright lemon sponge with a delicate elderflower-inspired finish. Light and beautifully fragrant.'),('Raspberry & white chocolate','fruit','#d9aeb2','A gentle balance of tart raspberry and creamy white chocolate sweetness.'),('Rose & pistachio','signature','#bcc5a9','Soft floral notes and the mellow, nutty character of pistachio. A romantic pairing.'),('Salted caramel','signature','#cfa773','Warm caramel sweetness with a subtle salty finish. Comforting, rich and celebratory.')]
flavour_html=''.join(f'<article class="flavour" data-category="{cat}"><span class="dot" style="background:{colour}" aria-hidden="true"></span><div><h3>{name}</h3><p>{desc}</p></div></article>' for name,cat,colour,desc in flavours)
page('flavours.html','Flavour menu','Explore a draft selection of flavour ideas for cakes and cupcake bouquets.',intro('As delicious<br>as they are <em>beautiful.</em>','A little inspiration for what’s inside. Discover classic favourites, fruity pairings and something a little unexpected.')+f'<section class="section" style="padding-top:20px"><div class="wrap"><div class="filter-bar" aria-label="Filter flavour ideas">'+''.join(f'<button class="filter" data-filter="{key}" aria-pressed="{str(key=="all").lower()}">{label}</button>' for key,label in [('all','All flavours'),('classic','The classics'),('fruit','Fresh & fruity'),('signature','Something special')])+f'</div><p id="filter-status" class="center note" role="status">6 flavour ideas shown</p><div class="flavours">{flavour_html}</div><div class="notice"><strong>Sample flavour menu.</strong> These pairings are draft ideas, not a confirmed product list. Please ask Adeela about current flavours, ingredients and dietary requirements before ordering.</div></div></section>'+cta())

details=[('bouquets.html','Cupcake bouquets','A bouquet.<br>A sweet <em>surprise.</em>','bouquet','Flowers that bring a little extra joy. Beautiful buttercream blooms, arranged as a bouquet and ready to become a very thoughtful gift.','Cupcake bouquets','Think birthdays, thank-yous, anniversaries — or a lovely surprise just because. Share a favourite colour and the feeling you have in mind.','A palette to fall for','Blush pink, soft lilac, ivory and a touch of sage. Your palette is a starting point for a design that feels personal.'),('celebration-cakes.html','Celebration cakes','The sweetest<br><em>centrepiece.</em>','cake','Some moments deserve a cake of their own. A beautiful focal point, a favourite flavour, and a design that makes the occasion feel special.','Celebration cakes','From a quiet birthday gathering to a milestone worth celebrating, tell me your guest count, colour palette and any meaningful details.','Made around your moment','Romantic florals, delicate colour and considered details. Together we can explore the right direction for your celebration.'),('weddings.html','Wedding cupcake bouquets','For your<br><em>forever moment.</em>','wedding','Romantic cupcake bouquets for a day full of love. A delicate floral detail for your wedding table, a thoughtful gift, or something sweet to share.','Wedding cupcake bouquets','Share your wedding date, venue, guest numbers and palette. Whether you imagine ivory blooms or soft touches of colour, we’ll start with your vision.','Beautifully in harmony','Consider the flowers, stationery and textures of your day. A coordinated palette can make your cupcake bouquets feel naturally part of the celebration.')]
for filename,title,heading,im,desc,category,copy,sub,subcopy in details:
    href='contact.html?collection='+category.replace(' ','%20')
    page(filename,title,desc,f'<div class="wrap"><div class="breadcrumb"><a href="index.html#collections">The collections</a> / {title}</div><section class="detail-hero split">{photo(im,"Illustrative "+title.lower(),eager=True)}<div class="split-copy"><h1>{heading}</h1><p>{desc}</p><p>{copy}</p>{button(href,"Enquire about this collection")}<p class="note">Designed around your occasion. Final design, size, price and availability confirmed on enquiry.</p></div></section></div><section class="section {"lilac" if im=="cake" else "sage"}"><div class="wrap split"><div><h2>{sub}</h2><p>{subcopy}</p><div class="palette" aria-label="Blush, lilac, sage and ivory colour inspiration"><span class="swatch" style="background:#e6c4c5" title="Blush"></span><span class="swatch" style="background:#d2c4de" title="Lilac"></span><span class="swatch" style="background:#b7c0a9" title="Sage"></span><span class="swatch" style="background:#faf5e9" title="Ivory"></span></div></div><div><h3>Beauty, inside and out.</h3><p>Browse the flavour ideas, then tell me what you love. Your creation should feel just as special in its flavour as it does in its design.</p>{link("flavours.html","Explore the flavour menu")}</div></div></section>'+cta())

page('contact.html','Contact','Prepare your cake enquiry and contact Baked by Adeela on Instagram.',intro('Let’s make<br>something <em>lovely.</em>','Every beautiful creation begins with a conversation. Tell me a little about your occasion.')+f'''<div class="wrap contact-grid"><aside><h2>I’d love to hear<br>your <em>ideas.</em></h2><p>Not quite sure where to begin? A date, a colour or a little inspiration is all you need to get started.</p><div class="contact-item"><span>Instagram · contact Adeela here</span><p><a class="text-link" href="{IG}" target="_blank" rel="noopener noreferrer">@bakedbyadeela {arrow}</a></p></div><div class="contact-item"><span>Email · placeholder</span><p>hello@bakedbyadeela.example</p><small>Sample address — not monitored.</small></div><div class="contact-item"><span>Telephone · placeholder</span><p>+44 7700 900123</p><small>Fictional UK number — not in service.</small></div><div class="contact-item"><span>Collection &amp; delivery</span><p>Please ask about location and arrangements.</p></div></aside><div><form id="enquiry-form"><div class="form-grid"><div class="field"><label for="name">Your name *</label><input id="name" name="name" autocomplete="name" required maxlength="100" placeholder="First and last name"></div><div class="field"><label for="email">Email address *</label><input id="email" name="email" type="email" autocomplete="email" required maxlength="150" placeholder="you@example.com"></div><div class="field full"><label for="collection">What are you dreaming of? *</label><select id="collection" name="collection" required><option value="">Choose a collection</option><option>Cupcake bouquets</option><option>Celebration cakes</option><option>Wedding cupcake bouquets</option><option>Something else</option></select></div><div class="field"><label for="date">Celebration date *</label><input id="date" name="date" type="date" required></div><div class="field"><label for="guests">Guests / cupcakes</label><input id="guests" name="guests" type="number" min="1" max="10000" placeholder="Approximate number"></div><div class="field full"><label for="message">Tell me a little more *</label><textarea id="message" name="message" required minlength="10" maxlength="3000" placeholder="Your occasion, colours, favourite flowers, budget and any dietary requirements…"></textarea></div></div><p class="form-note">This form prepares a message for you to copy and send on Instagram. Nothing is sent or stored by this website.</p><button class="button" type="submit">Prepare my enquiry {arrow}</button></form><section class="result" id="enquiry-result" hidden aria-labelledby="result-title"><h3 id="result-title" tabindex="-1">Your message is ready.</h3><p>Copy it below, then open Instagram and send it to @bakedbyadeela. Your enquiry has not been sent yet.</p><label for="message-preview">Your enquiry message</label><textarea id="message-preview" readonly></textarea><div class="result-actions"><button class="button" id="copy-enquiry" type="button">Copy message</button>{button(IG,'Open Instagram',True)}</div><p id="copy-status" role="status" class="note"></p></section></div></div>''')

posts=[('choosing-your-palette.html','A palette for your perfect occasion','bouquet','Colour inspiration','Start with a feeling, choose a favourite shade, and let the little details fall into place.'),('a-bouquet-with-a-difference.html','A bouquet with a delicious difference','wedding','Thoughtful gifting','Flowers or cake? A cupcake bouquet brings both ideas together in one lovely gesture.'),('planning-your-celebration.html','The little guide to a lovely cake enquiry','cake','Celebration notes','A few helpful details to have in mind when you begin planning your celebration cake.')]
page('blog.html','The journal','Colour inspiration, thoughtful gifting and celebration ideas from Baked by Adeela.',intro('Notes from<br>the <em>cake studio.</em>','A little inspiration, a few thoughtful details, and ideas for your next lovely celebration.')+'<section class="section"><div class="wrap journal">'+''.join(f'<article><a href="{url}">{photo(im,title)}<h2>{title}</h2><p class="meta">{cat} · 3 minute read</p></a><p>{copy}</p>{link(url,"Read the story")}</article>' for url,title,im,cat,copy in posts)+'</div></section>'+cta())
articles=[('''<h2>Begin with a feeling</h2><p>Before choosing individual colours, think about the mood of the occasion. Is it quiet and romantic, fresh and joyful, or soft and understated? A clear feeling makes the smaller decisions easier.</p><h2>Choose one colour to lead</h2><p>Blush pink makes a beautiful starting point for a romantic palette. Lilac brings a gentle, playful character, while ivory feels quietly timeless. Pick one shade you love, then let the others support it.</p><h2>Let greenery give the colours space</h2><p>A touch of sage can soften a pink and lilac combination. Think of it as breathing room between the blooms: it gives the floral shapes definition without competing for attention.</p><h2>Bring your inspiration</h2><p>A ribbon, an invitation, or a photograph of your flowers can communicate a palette more clearly than a colour name alone. Share these details when enquiring, and remember that colours look different on screens and in different light.</p>'''),('''<h2>A familiar gesture, reimagined</h2><p>A bunch of flowers is a wonderful way to say thank you. A cake invites people to pause and share something sweet. A cupcake bouquet combines the spirit of both: a floral arrangement with a delicious surprise.</p><h2>Make the thought personal</h2><p>Consider the recipient’s favourite colours, the reason for the gift, and how many people might share it. A soft ivory palette feels very different from a bouquet full of blush and lilac — neither needs to be complicated to feel special.</p><h2>Think about the moment it arrives</h2><p>Will it be presented at a party, taken to a dinner, or given as a quiet surprise? Mention your plans when enquiring so that packaging, timing and handling can be discussed.</p><h2>Ask before ordering</h2><p>Check flavours, ingredients and dietary needs directly before confirming. Share the celebration date and ask about availability and collection or delivery arrangements.</p>'''),('''<h2>Start with the date</h2><p>Your celebration date is the most useful place to begin. Include it in your first message, even if you have not decided on a design. Availability needs to be confirmed before the finer details are agreed.</p><h2>Have a rough guest count</h2><p>Knowing how many people you expect to serve helps shape the conversation about cake size or cupcake quantities. An estimate is a helpful starting point; the final serving requirements can be discussed together.</p><h2>Share what you love</h2><p>You do not need a complete design. A colour palette, a favourite flower, or a few inspiration images can be enough to explain your direction. Include any words, names or details that matter to your celebration.</p><h2>Include the practical details</h2><ul><li>The date and type of occasion.</li><li>Your estimated guest count and budget.</li><li>Your preferred colours and flavours.</li><li>Any allergies or dietary requirements.</li><li>Your collection or delivery needs.</li></ul><p>The contact page brings these details together into a message you can send to Adeela on Instagram. A message begins the conversation; it does not confirm a booking.</p>''')]
for (url,title,im,cat,copy),text in zip(posts,articles):
    page(url,title,copy,intro(title,cat+' · Studio journal')+f'<article class="article wrap"><img src="assets/{im}.jpg" alt="Illustrative floral cake design" width="1122" height="1402"><p class="note">Illustrative design imagery</p>{text}{link("contact.html","Start your enquiry")}<br>{link("blog.html","Back to the journal")}</article>')

(DIST/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#efddd8"/><text x="32" y="47" text-anchor="middle" font-family="Georgia,serif" font-size="47" fill="#423a36">A</text></svg>')
print(f'Built {len(list(DIST.glob("*.html")))} pages.')
